#!/usr/bin/env python3
"""Day 053: Range partitioning and trailing hot range."""
import argparse
from collections import defaultdict

def find_shard(key: int, bounds: list[tuple[int, int]]) -> int:
for i, (lo, hi) in enumerate(bounds):
if lo <= key < hi:
return i
return len(bounds) - 1

def main():
p = argparse.ArgumentParser()
p.add_argument("--writes", type=int, default=10000)
p.add_argument("--split-at", type=int, default=0, help="Split last range at this key (0=none)")
args = p.parse_args()
bounds = [(0, 2500), (2500, 5000), (5000, 7500), (7500, 10**9)]
if args.split_at:
bounds = [(0, 2500), (2500, 5000), (5000, 7500), (7500, args.split_at), (args.split_at, 10**9)]
writes = defaultdict(int)
for i in range(args.writes):
key = 8000 + i # time-ordered IDs in hot tail
writes[find_shard(key, bounds)] += 1
total = sum(writes.values())
print(f"Sequential writes={total} ranges={len(bounds)}")
for i in range(len(bounds)):
c = writes.get(i, 0)
print(f" range {i} [{bounds[i][0]},{bounds[i][1]}): {c} writes ({100*c/total:.1f}%)")
hot = max(writes.values()) / total
print(f"Hottest range write share: {hot:.1%}")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 056: Stale routing cache after partition move."""
import argparse

class Router:
def __init__(self):
self.version = 1
self.routes = {"p0": "node-a", "p1": "node-b"}

def move(self, part: str, dest: str):
self.routes[part] = dest
self.version += 1

class Client:
def __init__(self, router: Router):
self.router = router
self.cache = {}
self.cache_version = 0
self.stale_errors = 0
self.ok = 0

def resolve(self, part: str, force_refresh: bool = False):
if not force_refresh and part in self.cache and self.cache_version == self.router.version:
return self.cache[part]
node = self.router.routes[part]
self.cache[part] = node
self.cache_version = self.router.version
return node

def request(self, part: str, force_refresh: bool = False):
node = self.resolve(part, force_refresh)
actual = self.router.routes[part]
if node != actual:
self.stale_errors += 1
return False
self.ok += 1
return True

def main():
p = argparse.ArgumentParser()
p.add_argument("--refresh-after-stale", action="store_true")
args = p.parse_args()
r = Router()
c = Client(r)
for _ in range(3):
c.request("p0")
r.move("p0", "node-c")
ok = c.request("p0")
if not ok and args.refresh_after_stale:
c.request("p0", force_refresh=True)
print(f"router v{r.version} routes={r.routes}")
print(f"ok={c.ok} stale_errors={c.stale_errors}")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 057: Local vs global secondary index fan-out."""
import argparse

def local_lookup(email: str, shards: list[dict]) -> list[str]:
hits = []
for s in shards:
if email in s.get("email_index", {}):
hits.append(s["email_index"][email])
return hits

def global_lookup(email: str, gindex: dict) -> str | None:
return gindex.get(email)

def main():
p = argparse.ArgumentParser()
p.add_argument("--change-email", action="store_true")
args = p.parse_args()
shards = [{"id": 0, "users": {"u1": "a@x.com"}, "email_index": {"a@x.com": "u1"}},
{"id": 1, "users": {}, "email_index": {}}]
gindex = {"a@x.com": ("shard0", "u1")}
email = "a@x.com"
print("LOCAL read fan-out:", len(shards), "shards queried")
print(" result:", local_lookup(email, shards))
print("GLOBAL read fan-out: 1 index shard")
print(" result:", global_lookup(email, gindex))
if args.change_email:
new = "b@x.com"
shards[0]["email_index"].pop(email)
shards[0]["email_index"][new] = "u1"
gindex.pop(email)
gindex[new] = ("shard0", "u1")
print(f"Email change write fan-out: local=1 shard, global=2 (primary+index)")
else:
print("Write fan-out: local=1, global=2 on indexed update")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 061: Snapshot isolation simulated with row versions."""
import argparse
from dataclasses import dataclass

@dataclass
class Version:
value: int
created_by: int
deleted_by: int | None = None

class SnapshotDB:
def __init__(self):
self.rows: dict[int, list[Version]] = {1: [Version(10, 0)]}
self.tx_counter = 0
self.active: dict[int, int] = {}

def begin(self) -> int:
self.tx_counter += 1
self.active[self.tx_counter] = self.tx_counter
return self.tx_counter

def read(self, tx: int, key: int) -> int | None:
for v in reversed(self.rows[key]):
if v.deleted_by and v.deleted_by <= tx:
continue
if v.created_by <= tx:
return v.value
return None

def write(self, tx: int, key: int, value: int):
for v in self.rows[key]:
if v.deleted_by is None and v.created_by not in (0, tx):
raise RuntimeError(f"write-write conflict: tx{tx} vs tx{v.created_by}")
cur = self.read(tx, key)
if cur is not None:
self.rows[key][-1].deleted_by = tx
self.rows[key].append(Version(value, tx))

def main():
p = argparse.ArgumentParser()
p.add_argument("--conflict", action="store_true")
args = p.parse_args()
db = SnapshotDB()
t1 = db.begin()
t2 = db.begin()
print(f"t1 sees: {db.read(t1, 1)}")
db.write(t2, 1, 99)
print(f"t1 still sees: {db.read(t1, 1)}")
if args.conflict:
try:
db.write(t1, 1, 50)
except RuntimeError as e:
print("conflict:", e)

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 067: Two-phase commit with coordinator crash."""
import argparse
from enum import Enum

class State(str, Enum):
INIT = "init"
PREPARED = "prepared"
COMMITTED = "committed"
ABORTED = "aborted"

class Participant:
def __init__(self, name: str):
self.name = name
self.state = State.INIT

def prepare(self) -> bool:
self.state = State.PREPARED
return True

def commit(self):
self.state = State.COMMITTED

def abort(self):
self.state = State.ABORTED

def run(crash: bool):
parts = [Participant("db1"), Participant("db2")]
votes = [p.prepare() for p in parts]
if all(votes):
if crash:
print("COORDINATOR CRASH after prepare - participants blocked:")
for p in parts:
print(f" {p.name}: {p.state.value}")
return
for p in parts:
p.commit()
else:
for p in parts:
p.abort()
print("final:", {p.name: p.state.value for p in parts})

def main():
p = argparse.ArgumentParser()
p.add_argument("--crash", action="store_true")
args = p.parse_args()
run(args.crash)

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 069: Unreliable network + idempotency keys."""
import argparse
import random

class Server:
def __init__(self):
self.seen: set[str] = set()
self.charges = 0

def charge(self, key: str, idempotent: bool) -> str:
if idempotent and key in self.seen:
return "deduped"
if idempotent:
self.seen.add(key)
self.charges += 1
return "ok"

def network_deliver(messages: list[str], drop: float, dupe: float, rng: random.Random):
out = []
for m in messages:
if rng.random() < drop:
continue
out.append(m)
if rng.random() < dupe:
out.append(m)
return out

def main():
p = argparse.ArgumentParser()
p.add_argument("--idempotent", action="store_true")
p.add_argument("--drop", type=float, default=0.2)
p.add_argument("--dupe", type=float, default=0.3)
args = p.parse_args()
rng = random.Random(7)
srv = Server()
msgs = ["pay:order42"] * 3
delivered = network_deliver(msgs, args.drop, args.dupe, rng)
for m in delivered:
key = m.split(":")[1]
print(m, "->", srv.charge(key, args.idempotent))
print(f"total charges={srv.charges} idempotent={args.idempotent}")

if __name__ == "__main__":
main()
